def _make_assistant_message(*, blocks: list, usage: dict | None = None):
    """Build a duck-typed AssistantMessage stand-in. The agent code uses
    isinstance() so tests must use the real class — but with controlled fields.
    """
    from claude_agent_sdk import AssistantMessage

    return AssistantMessage.__new__(AssistantMessage).__class__(
        content=blocks,
        usage=usage,
        model="test-model",
        parent_tool_use_id=None,
    )


def _make_stream_event(event_dict: dict):
    from claude_agent_sdk import StreamEvent

    return StreamEvent.__new__(StreamEvent).__class__(
        uuid="stream-event-uuid",
        session_id="test-session",
        parent_tool_use_id=None,
        event=event_dict,
    )


