class TestAgentClient:
    """Tests for AgentClient."""

    def test_status_before_start(self, agent: AgentClient) -> None:
        status = agent.status
        assert status["agent_id"] == "test-agent"
        assert status["session_id"] is None
        assert status["total_cost_usd"] == 0.0

    def test_status_has_working_dir(self, agent: AgentClient) -> None:
        assert "agent" in agent.status["working_dir"]

    def test_status_has_timestamp(self, agent: AgentClient) -> None:
        assert agent.status["timestamp"] is not None

    async def test_send_message_increments_counter(
        self, agent: AgentClient, metrics: MagicMock
    ) -> None:
        """Sending a message increments the inbound counter even when the SDK
        client is None (emits an error and returns)."""
        await agent.send_message(content="hello")
        metrics.messages_total.labels.assert_called_with(direction="inbound")
        metrics.messages_total.labels().inc.assert_called_once()

    async def test_send_before_start_emits_error(
        self, agent: AgentClient, on_event: AsyncMock
    ) -> None:
        await agent.send_message(content="hi")
        on_event.assert_awaited()
        msg = on_event.await_args.args[0]
        assert isinstance(msg, ErrorMessage)
        assert "not connected" in msg.content

    async def test_clear_resets_session_and_reconnects(
        self, agent: AgentClient
    ) -> None:
        await agent.start()
        agent._session_id = "old-session"
        await agent.clear()
        assert agent.status["session_id"] is None

    async def test_clear_preserves_accumulator(self, agent: AgentClient) -> None:
        """Cost/token totals must NOT reset on /clear (process-scoped)."""
        await agent.start()
        agent._accumulator.total_cost_usd = 1.50
        agent._accumulator.total_input_tokens = 1000
        await agent.clear()
        assert agent._accumulator.total_cost_usd == 1.50
        assert agent._accumulator.total_input_tokens == 1000
        # Per-turn snapshot IS reset
        assert agent._accumulator.last_input_tokens == 0

    async def test_sequential_message_processing(self, agent: AgentClient) -> None:
        """Messages are processed sequentially via lock."""
        call_order: list[int] = []

        async def slow_process(*, content, source=None):
            call_order.append(1)
            await asyncio.sleep(0.05)
            call_order.append(2)

        with patch.object(agent, "_process_message", side_effect=slow_process):
            await asyncio.gather(
                agent.send_message(content="a"),
                agent.send_message(content="b"),
            )
        assert call_order == [1, 2, 1, 2]


